document.addEventListener('readystatechange', (event) => {
  if (event.target.readyState === 'complete') {
    let count_intakes = document.querySelectorAll('select[name="apply_now_sits_urls"] option').length;
    if (count_intakes <= 0) {
      document.querySelectorAll('.btn-primary--apply').forEach(function (el) {
        el.remove();
      });
      document.querySelectorAll('.btn-primary--speak').forEach(function (el) {
        el.remove();
      });
      document.querySelector('#pre-app-modal');
      document.querySelector('#speak-to-someone-modal');
      document.querySelector('.btn-primary--interest').style.display = 'block';
      //document.querySelector('.summary .btn-primary').removeAttribute('data-theme');
    }

  }
});

