document.addEventListener("DOMContentLoaded", () => {

    const placeholders = document.querySelectorAll('.discover-uni-placeholder');
    if (!placeholders.length) return;

    function adjustHeightForElement(el) {
        const width = el.offsetWidth;

        if (width < 390) {
            el.style.height = "700px";
        } else if (width <= 767) {
            el.style.height = "630px";
        } else if (width <= 1023) {
            el.style.height = "500px";
        } else if (width <= 1279) {
            el.style.height = "330px";
        } else {
            el.style.height = "450px";
        }
    }

    // --- Lazy-load widget ---
    const loadWidget = (placeholder) => {
        const embed = document.createElement('embed');
        embed.src = placeholder.dataset.src;
        embed.className = "discover-uni-widget-c4W74bnm-du";
        embed.style.width = "100%";

        placeholder.replaceWith(embed);

        // Apply height once the embed has rendered
        requestAnimationFrame(() => {
            adjustHeightForElement(embed);
        });

        // Recalculate on resize (per widget)
        window.addEventListener('resize', () => {
            adjustHeightForElement(embed);
        });
    };

    // --- Observe placeholders ---
    const observer = new IntersectionObserver((entries) => {
        entries.forEach(entry => {
            if (!entry.isIntersecting) return;

            loadWidget(entry.target);
            observer.unobserve(entry.target);
        });
    }, {
        rootMargin: "300px" // load shortly before it scrolls into view
    });

    placeholders.forEach(ph => observer.observe(ph));
});

